with remaining_keys as (select plan, customer_id from subscriptions except all select plan, customer_id from subscriptions where status = 'PAUSED'), verified as (select s.* from subscriptions s join remaining_keys k on s.plan = k.plan and s.customer_id = k.customer_id) select s.id, s.customer_id, s.plan, s.end_date, (select sum(t2.balance) from accounts t2 where t2.customer_id = s.customer_id) as sum_account_balance from verified s order by end_date desc nulls last, customer_id;
